package corpagent;

import corpagent.data.*;
import corpagent.db.*;
import corpagent.files.*;
import corpagent.tools.*;
import corpagent.util.*;
import java.nio.file.*;
import java.util.*;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;

/** No remote services. Source selection, access boundaries and actual template cell placement. */
public final class ScenarioRulesTest {
    static int checks;static void check(boolean value,String message){if(!value)throw new AssertionError(message);checks++;}
    public static void main(String[] args)throws Exception{
        Path root=Path.of(".").toAbsolutePath(),base=Files.createTempDirectory(root.resolve("build_test"),"scenario-rules-");DataStore store=new DataStore(base.toString());String it="Методология ИТ проектов",pm="Методология LPG";
        check(MethodologyRouter.sources("Ответь по методологии ИТ",store).equals(List.of(it)),"Cyrillic IT routing");check(MethodologyRouter.sources("Методология IT",store).equals(List.of(it)),"Latin IT routing");check(MethodologyRouter.sources("Методология проектного управления",store).equals(List.of(pm)),"PM routing");check(MethodologyRouter.sources("Сравни методологии IT и LPG",store).equals(List.of(it,pm)),"dual source routing");check(MethodologyRouter.empty(store,it),"empty reference recognized");
        String itPath=Json.str(store.getDatabase(it),"path","");for(int i=1;i<=9;i++)SqliteHelper.executeQuery(itPath,"INSERT INTO frameworks(name,description) VALUES('item"+i+"','"+(i==9?"BEYOND_PREVIEW_MARKER":"item")+"')");check(!MethodologyRouter.empty(store,it),"populated reference recognized");
        ToolExecutor executor=new ToolExecutor(store,new ToolRegistry(store));executor.setActiveDatabase(itPath,it);executor.setQueryDatabases(List.of(it,pm));check(executor.executeBuiltinSql("db_search",Map.of("text","BEYOND_PREVIEW_MARKER")).contains("BEYOND_PREVIEW_MARKER"),"search beyond first five rows");check(executor.executeBuiltinSql("db_search",Map.of("text","missing-marker")).contains("не найдено"),"missing text search");check(executor.executeBuiltinSql("db_search",Map.of("database","unselected","text","marker")).contains("не выбрана"),"unselected source denied");check(executor.executeBuiltinSql("db_execute",Map.of("sql","DELETE FROM frameworks WHERE id=9")).contains("read-only"),"reference remains read only");check(executor.systemDbTools().size()==3,"three built-in database tools");
        check(DocumentPlan.intent("Подготовь паспорт проекта","Создание паспорта проекта в Excel")==IntentRouter.Intent.EXCEL,"selected passport generator executes");check(DocumentPlan.intent("Подготовь статус проекта","Создание статуса проекта в PPT")==IntentRouter.Intent.PRESENTATION,"selected status generator executes");check(DocumentPlan.excelKeys("Создай Excel паспорт с разделом рисков",null)[0].equals("паспорт"),"primary document wins secondary topic");check(DocumentPlan.excelKeys("Создай Excel реестр рисков, используй паспорт",null)[0].contains("рисков"),"risk register wins secondary passport");
        FileCreator creator=new FileCreator(base.resolve("output").toString(),root.toString());for(String brand:List.of("Гипер Лента","Группа Лента","Супер Лента"))check(creator.getPresentationTemplate("Создай презентацию по шаблону "+brand,null).toLowerCase().contains(brand.toLowerCase()),"presentation brand template");check(creator.getPresentationTemplate("Подготовь статус проекта","Создание статуса проекта в PPT").contains("Статус"),"status template selected");check(creator.getPresentationTemplate("Создай презентацию в шаблоне Супер Ленты, раздел статус",null).contains("презентаций"),"section title does not override template");
        String passport=creator.createExcel("project_name;LOCAL_SYNTHETIC_PROJECT\nreasons;Synthetic reason\nbudget;Нет данных\nteam;Synthetic team",creator.getCorporateExcelTemplate("паспорт"));try(var wb=new XSSFWorkbook(Files.newInputStream(Path.of(passport)))){check(wb.getSheetAt(0).getRow(0).getCell(0).getStringCellValue().contains("LOCAL_SYNTHETIC_PROJECT"),"passport title filled");check(wb.getSheetAt(0).getRow(2).getCell(0).getStringCellValue().equals("Synthetic reason"),"passport body filled");check(wb.getSheetAt(0).getRow(13).getCell(0).getStringCellValue().equals("Нет данных"),"unknown budget is not zero");check(wb.getSheetIndex("Пример_Паспорт")<0,"example sheet removed");}
        String risk=creator.createExcel("id;date;title;description;category;probability;impact;priority;owner;status;mitigation;due_date\n1;;LOCAL_SYNTHETIC_RISK;\"quoted;description\";;high;high;high;Test;open;Synthetic action;",creator.getCorporateExcelTemplate("риск"));try(var wb=new XSSFWorkbook(Files.newInputStream(Path.of(risk)))){check(wb.getSheetAt(0).getRow(18).getCell(7).getStringCellValue().equals("LOCAL_SYNTHETIC_RISK"),"risk data in template table");check(wb.getSheetAt(0).getRow(18).getCell(9).getStringCellValue().equals("quoted;description"),"quoted semicolon retained");check(wb.getSheetAt(0).getRow(18).getCell(14).getStringCellValue().equals("Test"),"risk owner column correct");}
        DatabaseManager manager=new DatabaseManager(base.resolve("databases").toString(),base.resolve("backups").toString(),store);var project=ProjectManager.createProject(store,manager,"Synthetic atomic protocol","","","atomic_protocol");check(project.success,"protocol fixture created");String path=Json.str(store.getDatabase("atomic_protocol"),"path","");
        Map<String,Object> draft=new LinkedHashMap<>();draft.put("meeting",Map.of("title","SYNTHETIC_ATOMIC_MEETING"));draft.put("decisions",List.of(Map.of("decision","Synthetic decision")));draft.put("tasks",List.of(Map.of("title","SYNTHETIC_ACTION_A"),Map.of("title","SYNTHETIC_ACTION_B")));long meeting=ProtocolWriter.persist(path,"1",draft);check(meeting>0&&SqliteHelper.getTableRows(path,"tasks",10).size()==2,"all protocol tasks committed");
        draft.put("tasks",List.of(Map.of("title","SYNTHETIC_VALID"),Map.of("title","")));boolean rolledBack=false;try{ProtocolWriter.persist(path,"1",draft);}catch(IllegalArgumentException expected){rolledBack=true;}check(rolledBack&&SqliteHelper.getTableRows(path,"meetings",10).size()==1&&SqliteHelper.getTableRows(path,"tasks",10).size()==2,"invalid protocol group rolled back atomically");
        executor.setActiveDatabase(path,"atomic_protocol");executor.setWriteConfirmation((sql,name)->false);check(!executor.allowStructuredWrite("Synthetic protocol"),"structured writes require confirmation");
        String literal=ProjectDocumentData.literalTable("Создай паспорт. Данные строго: Name;Value\nSYNTHETIC_LITERAL;42",null);check(literal.equals("Name;Value\nSYNTHETIC_LITERAL;42"),"literal user table retained exactly");String literalFile=creator.createExcel(literal,creator.getCorporateExcelTemplate("паспорт"));String literalText=FileExtractor.extractText(Path.of(literalFile).toFile());check(literalText.contains("SYNTHETIC_LITERAL")&&literalText.contains("42"),"all Excel sheets extracted");
        String riskData=ProjectDocumentData.risks(path);check(riskData!=null&&!riskData.contains("synthetic invented risk"),"empty risk registry does not invent rows");String passportData=ProjectDocumentData.passport(path);check(passportData.contains("Synthetic atomic protocol")&&passportData.contains("Нет данных"),"passport exports only factual project data");
        Path docx=base.resolve("table.docx");try(var document=new org.apache.poi.xwpf.usermodel.XWPFDocument();var output=Files.newOutputStream(docx)){document.createTable(1,1).getRow(0).getCell(0).setText("SYNTHETIC_DOCX_TABLE");document.write(output);}check(FileExtractor.extractText(docx.toFile()).contains("SYNTHETIC_DOCX_TABLE"),"DOCX table content extracted");
        Path xlsx=base.resolve("sheets.xlsx");try(var book=new XSSFWorkbook();var output=Files.newOutputStream(xlsx)){book.createSheet("first").createRow(0).createCell(0).setCellValue("first");var row=book.createSheet("second").createRow(0);row.createCell(0).setCellValue("SYNTHETIC_SECOND_SHEET");row.createCell(2).setCellValue("END");book.write(output);}check(FileExtractor.extractText(xlsx.toFile()).contains("SYNTHETIC_SECOND_SHEET;;END"),"later sheet and empty columns retained");
        for(String request:List.of("Шаблон Гипер Лента","Шаблон Группа Лента","Шаблон Супер Лента","Шаблон статуса проекта")){String file=creator.createPptx("SYNTHETIC_TITLE\nSYNTHETIC_BODY",creator.getPresentationTemplate(request,null));try(var presentation=new org.apache.poi.xslf.usermodel.XMLSlideShow(Files.newInputStream(Path.of(file)))){check(java.util.Arrays.stream(presentation.getSlides().get(0).getPlaceholders()).allMatch(p->p.getText().isBlank())&&FileExtractor.extractText(Path.of(file).toFile()).contains("SYNTHETIC_TITLE"),"template placeholders cleared while content retained");}}
        check(creator.getPresentationTemplate("Сделай презентацию в корпоративном стиле ленты на свободную тему, три любых слайда.",null)!=null,"corporate style natural-language template selection");
        check(PresentationPlan.slideCount("три любых слайда")==3&&PresentationPlan.slideCount("5 слайдов")==5,"natural-language slide count");
        SqliteHelper.executeQuery(itPath,"CREATE TABLE source_documents(id INTEGER PRIMARY KEY,filename TEXT,notice TEXT)");
        SqliteHelper.executeQuery(itPath,"CREATE TABLE source_chunks(id INTEGER PRIMARY KEY,document_id INTEGER,section TEXT,line_start INTEGER,line_end INTEGER,content TEXT)");
        SqliteHelper.executeQuery(itPath,"INSERT INTO source_documents VALUES(1,'synthetic.md','Неполная выгрузка')");
        SqliteHelper.executeQuery(itPath,"INSERT INTO source_chunks VALUES(1,1,'Согласование бюджета',10,14,'Перед стартом бюджет согласуется спонсором. SYNTHETIC_REFERENCE_VALUE')");
        String located=executor.executeBuiltinSql("db_search",Map.of("database",it,"text","Как СОГЛАСОВЫВАЕТСЯ БЮДЖЕТ?"));
        check(located.contains("SYNTHETIC_REFERENCE_VALUE")&&located.contains("synthetic.md")&&located.contains("10–14"),"Unicode ranked reference search with source location");
        check(ReferenceSearch.search(itPath,"UNRELATED_XYZ").isEmpty(),"unmatched reference question does not invent evidence");
        System.out.println("ScenarioRulesTest OK ("+checks+" checks)");
    }
}
